package com.bankease.service;
import com.bankease.dto.BankDtos.*; import com.bankease.entity.*; import com.bankease.repository.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.security.SecureRandom; import java.util.*;
@Service public class BankingService{private final AccountRepository accounts;private final TransactionRepository txs;private final UserRepository users;private final SecureRandom random=new SecureRandom();public BankingService(AccountRepository accounts,TransactionRepository txs,UserRepository users){this.accounts=accounts;this.txs=txs;this.users=users;}@Transactional public CreateAccountResponse createAccount(String email){User u=users.findByEmail(email).orElseThrow();String no;do{no=String.format("BE%016d",Math.abs(random.nextLong()%10000000000000000L));}while(accounts.findByAccountNumber(no).isPresent());Account a=accounts.save(Account.builder().accountNumber(no).user(u).balance(BigDecimal.ZERO.setScale(2)).active(true).build());return new CreateAccountResponse(a.getId(),a.getAccountNumber(),a.getBalance(),u.getEmail(),a.getCreatedAt());}public List<AccountResponse> myAccounts(String email){return accounts.findByUserId(users.findByEmail(email).orElseThrow().getId()).stream().map(this::map).toList();}public AccountResponse getAccount(String email,String number){return map(owned(email,number));}@Transactional public AccountResponse deposit(String email,String number,MoneyRequest r){Account a=owned(email,number);ensureActive(a);a.setBalance(a.getBalance().add(r.amount()));saveTx(a,TransactionType.DEPOSIT,r.amount(),null,r.description());return map(a);}@Transactional public AccountResponse withdraw(String email,String number,MoneyRequest r){Account a=owned(email,number);ensureActive(a);if(a.getBalance().compareTo(r.amount())<0)throw new IllegalArgumentException("Insufficient balance");a.setBalance(a.getBalance().subtract(r.amount()));saveTx(a,TransactionType.WITHDRAWAL,r.amount(),null,r.description());return map(a);}@Transactional public void transfer(String email,TransferRequest r){if(r.fromAccount().equals(r.toAccount()))throw new IllegalArgumentException("Source and destination accounts must differ");Account from=owned(email,r.fromAccount());Account to=accounts.findForUpdate(r.toAccount()).orElseThrow(()->new NoSuchElementException("Destination account not found"));ensureActive(from);ensureActive(to);if(from.getBalance().compareTo(r.amount())<0)throw new IllegalArgumentException("Insufficient balance");from.setBalance(from.getBalance().subtract(r.amount()));to.setBalance(to.getBalance().add(r.amount()));saveTx(from,TransactionType.TRANSFER_OUT,r.amount(),to.getAccountNumber(),r.description());saveTx(to,TransactionType.TRANSFER_IN,r.amount(),from.getAccountNumber(),r.description());}public Page<TransactionResponse> history(String email,String number,int page,int size){Account a=owned(email,number);return txs.findByAccountIdOrderByCreatedAtDesc(a.getId(),PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100))).map(t->new TransactionResponse(t.getId(),t.getType().name(),t.getAmount(),t.getBalanceAfter(),t.getRelatedAccount(),t.getDescription(),t.getReferenceCode(),t.getCreatedAt()));}private Account owned(String email,String number){Account a=accounts.findByAccountNumber(number).orElseThrow(()->new NoSuchElementException("Account not found"));if(!a.getUser().getEmail().equalsIgnoreCase(email))throw new SecurityException("You do not own this account");return a;}private void ensureActive(Account a){if(!a.isActive())throw new IllegalStateException("Account is inactive");}private void saveTx(Account a,TransactionType type,BigDecimal amount,String related,String desc){txs.save(Transaction.builder().account(a).type(type).amount(amount).balanceAfter(a.getBalance()).relatedAccount(related).description(desc).referenceCode("TX-"+UUID.randomUUID()).build());}private AccountResponse map(Account a){return new AccountResponse(a.getId(),a.getAccountNumber(),a.getBalance(),a.isActive(),a.getCreatedAt());}}